class Solution {
public:
    int countPairs(vector<vector<int>>& coordinates, int k) {
        map<pair<int, int>, int> counts;
        int ans = 0;
        for (const auto& pt : coordinates) {
            int x = pt[0], y = pt[1];
            for (int a = 0; a <= k; a++) {
                int b = k - a;
                auto it = counts.find({x ^ a, y ^ b});
                if (it != counts.end()) ans += it->second;
            }
            counts[{x, y}]++;
        }
        return ans;
    }
};

class Solution {
    public int countPairs(List<List<Integer>> coordinates, int k) {
        Map<Long, Integer> counts = new HashMap<>();
        int ans = 0;
        for (List<Integer> pt : coordinates) {
            int x = pt.get(0), y = pt.get(1);
            for (int a = 0; a <= k; a++) {
                int b = k - a;
                int tx = x ^ a, ty = y ^ b;
                long key = (((long) tx) << 32) | (ty & 0xFFFFFFFFL);
                ans += counts.getOrDefault(key, 0);
            }
            long currKey = (((long) x) << 32) | (y & 0xFFFFFFFFL);
            counts.put(currKey, counts.getOrDefault(currKey, 0) + 1);
        }
        return ans;
    }
}

/**
 * @param {number[][]} coordinates
 * @param {number} k
 * @return {number}
 */
var countPairs = function(coordinates, k) {
    const counts = new Map();
    let ans = 0;
    for (const [x, y] of coordinates) {
        for (let a = 0; a <= k; a++) {
            const b = k - a;
            const tx = x ^ a, ty = y ^ b;
            const key = tx + ',' + ty;
            ans += counts.get(key) || 0;
        }
        const currKey = x + ',' + y;
        counts.set(currKey, (counts.get(currKey) || 0) + 1);
    }
    return ans;
};
